<?php
/** Generative media: how image generation works, prompting for images, video and audio, rights, labels and deepfakes. */

return [
    'id' => 'genmedia', 'family' => 'ai', 'after' => null,
    'title' => L('AI per immagini, video e audio', 'AI for Images, Video and Audio'), 'short' => L('Media generativi', 'Generative Media'), 'level' => L('Base', 'Basics'),
    'desc' => L('Creare immagini, video, voci e musica con l’AI: come funzionano i modelli, come scrivere le richieste, diritti, etichette dei contenuti e deepfake.', 'Creating images, video, voices and music with AI: how the models work, how to write requests, rights, content labels and deepfakes.'),
    'lessons' => [
        lesson('how', L('Come nascono le immagini', 'How images are made'), [
            P('La maggior parte dei generatori di immagini usa modelli di **diffusione**: partono da puro rumore e lo “ripuliscono” passo dopo passo, guidati dalla descrizione testuale, finché emerge un’immagine. Sono addestrati su enormi raccolte di immagini con didascalie.', 'Most image generators use **diffusion** models: they start from pure noise and “clean” it step by step, guided by the text description, until an image emerges. They are trained on huge collections of captioned images.'),
            P('Strumenti diffusi: Midjourney, la generazione di immagini dentro ChatGPT e Gemini, Adobe Firefly, e modelli aperti come Stable Diffusion e Flux che si possono usare anche in locale. Oltre a creare da zero, sanno **modificare** una foto (togliere oggetti, cambiare lo sfondo, allargare l’inquadratura).', 'Common tools: Midjourney, image generation inside ChatGPT and Gemini, Adobe Firefly, and open models like Stable Diffusion and Flux that can also run locally. Besides creating from scratch, they can **edit** a photo (remove objects, change the background, extend the frame).'),
        ], [
            Q('h1', L('Da che cosa parte un modello di diffusione?', 'What does a diffusion model start from?'), [L('Da rumore casuale', 'From random noise'), L('Da una foto vera sempre', 'Always from a real photo'), L('Da un disegno a mano', 'From a hand drawing'), L('Da un video', 'From a video')], 0, L('E lo ripulisce passo dopo passo.', 'And cleans it step by step.')),
            Q('h2', L('Quale di questi è un modello aperto per immagini?', 'Which of these is an open image model?'), ['Stable Diffusion', 'Excel', 'Outlook', 'Teams'], 0, L('Anche Flux.', 'Flux too.')),
            Q('h3', L('Oltre a creare, che cosa sanno fare questi strumenti?', 'Besides creating, what can these tools do?'), [L('Modificare foto esistenti', 'Edit existing photos'), L('Stampare', 'Print'), L('Inviare email', 'Send email'), L('Niente', 'Nothing')], 0, L('Togliere oggetti, cambiare sfondo…', 'Remove objects, change backgrounds…')),
        ], task('text', L('Spiega in una frase come funziona un modello di diffusione, usando le parole `rumore` (o `noise`) e `descrizione` (o `prompt`).', 'Explain in one sentence how a diffusion model works, using the words `noise` (or `rumore`) and `prompt` (or `descrizione`).'), '', [re('rumore|noise', L('Parli del rumore', 'You mention noise')), re('descrizion|prompt|testo|text', L('Parli della descrizione', 'You mention the description'))], '', 'Un modello di diffusione parte dal rumore e lo ripulisce passo dopo passo, guidato dalla descrizione, finché appare l’immagine.'), [
            dOrder(pSort(), [L('Rumore casuale', 'Random noise'), L('Primi contorni sfocati', 'First blurry outlines'), L('Forme riconoscibili', 'Recognisable shapes'), L('Immagine dettagliata', 'Detailed image')], L('I passi della diffusione.', 'The steps of diffusion.')),
            dFlash(pFlash(), [[L('I modelli di diffusione partono dal rumore', 'Diffusion models start from noise'), true], [L('Stable Diffusion funziona solo in cloud', 'Stable Diffusion only works in the cloud'), false], [L('Si può modificare lo sfondo di una foto', 'You can change a photo’s background'), true], [L('Le immagini generate copiano sempre una foto esistente', 'Generated images always copy an existing photo'), false]], L('Dal rumore all’immagine.', 'From noise to image.')),
        ]),
        lesson('prompt', L('Scrivere richieste per immagini', 'Writing prompts for images'), [
            P('Una buona richiesta per un’immagine descrive: **soggetto** (chi o cosa), **azione** e **ambientazione**, **stile** (fotografia, acquerello, illustrazione piatta, 3D), **composizione** (primo piano, dall’alto, grandangolo), **luce** e **colori**, e il **formato** (quadrato, 16:9).', 'A good image prompt describes: **subject** (who or what), **action** and **setting**, **style** (photo, watercolour, flat illustration, 3D), **composition** (close-up, top-down, wide-angle), **light** and **colours**, and the **format** (square, 16:9).'),
            C('Una volpe rossa che legge un libro su una panchina del Molo Audace a Trieste,
illustrazione ad acquerello, luce calda del tramonto, colori tenui,
inquadratura a figura intera, formato 16:9', 'text'),
            P('Poi si **itera**: cambia una cosa alla volta (“stessa scena, ma di notte”). Il testo dentro le immagini e le mani restano punti deboli frequenti: controllali. Per un marchio o un personaggio ricorrente, molti strumenti permettono di usare un’immagine di riferimento.', 'Then you **iterate**: change one thing at a time (“same scene, but at night”). Text inside images and hands remain frequent weak spots: check them. For a brand or recurring character, many tools let you use a reference image.'),
        ], [
            Q('p1', L('Che cosa descrive la “composizione”?', 'What does “composition” describe?'), [L('Inquadratura e punto di vista', 'Framing and point of view'), L('Il prezzo', 'The price'), L('Il nome del file', 'The file name'), L('La lingua', 'The language')], 0, L('Primo piano, dall’alto…', 'Close-up, top-down…')),
            Q('p2', L('Come si migliora un’immagine generata?', 'How do you improve a generated image?'), [L('Cambiando una cosa alla volta', 'Changing one thing at a time'), L('Riscrivendo tutto ogni volta', 'Rewriting everything each time'), L('Non si può', 'You cannot'), L('Aumentando la luminosità dello schermo', 'Raising screen brightness')], 0, L('Iterare con metodo.', 'Iterate methodically.')),
            Q('p3', L('Quali dettagli controllare spesso?', 'Which details often need checking?'), [L('Testo nell’immagine e mani', 'Text in the image and hands'), L('Il cielo sempre', 'The sky always'), L('Niente', 'Nothing'), L('Il bordo bianco', 'The white border')], 0, L('Punti deboli frequenti.', 'Frequent weak spots.')),
        ], task('text', L('Scrivi una richiesta per un’immagine che indichi **soggetto**, **stile**, **luce** e **formato** (es. 16:9 o quadrato).', 'Write an image prompt stating **subject**, **style**, **light** and **format** (e.g. 16:9 or square).'), '', [re('\w{3,}.{20,}', L('Descrivi un soggetto', 'You describe a subject')), re('illustrazion|acquerell|fotograf|3D|stile|style|watercolou?r|photo|cartoon|pittur|painting', L('Indichi lo stile', 'You state the style')), re('luce|light|tramonto|sunset|notte|night|alba|dawn', L('Indichi la luce', 'You state the light')), re('16:9|9:16|4:3|1:1|quadrat|square|vertical|orizzontal|landscape|portrait', L('Indichi il formato', 'You state the format'))], '', 'Un gatto astronauta che pianta un fiore sulla Luna, illustrazione 3D in stile cartone animato, luce morbida dal Sole basso, formato 16:9'), [
            dMatch(pMatch(), [[L('Soggetto', 'Subject'), L('Chi o cosa', 'Who or what')], [L('Stile', 'Style'), L('Acquerello, foto, 3D', 'Watercolour, photo, 3D')], [L('Composizione', 'Composition'), L('Inquadratura', 'Framing')], [L('Luce', 'Light'), L('Tramonto, studio, notte', 'Sunset, studio, night')], [L('Formato', 'Format'), '16:9']], L('Gli ingredienti di una richiesta visiva.', 'The ingredients of a visual prompt.')),
            dFlash(pFlash(), [[L('Indicare lo stile cambia molto il risultato', 'Stating the style changes the result a lot'), true], [L('Il testo nelle immagini è sempre perfetto', 'Text in images is always perfect'), false], [L('Si può chiedere la stessa scena di notte', 'You can ask for the same scene at night'), true], [L('Il formato non si può scegliere', 'The format cannot be chosen'), false]], L('Descrivere per immagini.', 'Describing in pictures.')),
        ]),
        lesson('video-audio', L('Video, voci e musica', 'Video, voices and music'), [
            P('I generatori di **video** (come Sora, Veo, Runway) creano brevi clip da un testo o animano un’immagine. Le richieste aggiungono il **movimento** della scena e della camera (“la camera avanza lentamente”, “ripresa dall’alto”) e la durata.', '**Video** generators (like Sora, Veo, Runway) create short clips from text or animate an image. Prompts add the **movement** of the scene and camera (“the camera slowly moves forward”, “aerial shot”) and the duration.'),
            P('Per l’**audio**: la **sintesi vocale** legge un testo con voci naturali in molte lingue (per esempio ElevenLabs), la **clonazione della voce** imita una voce da pochi campioni, i generatori di **musica** (come Suno) creano brani da una descrizione. La trascrizione (dall’audio al testo) è ormai molto precisa.', 'For **audio**: **text-to-speech** reads text with natural voices in many languages (for example ElevenLabs), **voice cloning** imitates a voice from a few samples, **music** generators (like Suno) create songs from a description. Transcription (audio to text) is now very accurate.'),
            Tip('Clonare la voce di qualcuno senza il suo consenso è scorretto e in molti casi illegale: usa solo la tua voce o voci con licenza.', 'Cloning someone’s voice without consent is wrong and often illegal: use only your own voice or licensed voices.'),
        ], [
            Q('v1', L('Che cosa aggiungi in una richiesta per un video?', 'What do you add in a video prompt?'), [L('Il movimento di scena e camera', 'Scene and camera movement'), L('Il numero di pixel', 'The pixel count'), L('Niente di diverso', 'Nothing different'), L('Il codice HTML', 'The HTML code')], 0, L('E la durata.', 'And the duration.')),
            Q('v2', L('Che cos’è la clonazione della voce?', 'What is voice cloning?'), [L('Imitare una voce da pochi campioni', 'Imitating a voice from a few samples'), L('Registrare un podcast', 'Recording a podcast'), L('Tradurre un testo', 'Translating a text'), L('Alzare il volume', 'Raising volume')], 0, L('Solo con consenso.', 'Only with consent.')),
            Q('v3', L('Si può clonare la voce di un collega senza chiedere?', 'Can you clone a colleague’s voice without asking?'), [L('No, serve il consenso', 'No, consent is needed'), L('Sì, sempre', 'Yes, always'), L('Solo per scherzo', 'Only as a joke'), L('Solo il venerdì', 'Only on Fridays')], 0, L('Spesso è anche illegale.', 'It is often illegal too.')),
        ], task('text', L('Scrivi una richiesta per un video di 8 secondi che descriva la **scena**, il **movimento della camera** e la **durata**.', 'Write a prompt for an 8-second video describing the **scene**, the **camera movement** and the **duration**.'), '', [re('camera|telecamera|inquadratura|ripresa|shot|pan|zoom', L('Il movimento della camera', 'The camera movement')), re('8\s*(secondi|seconds|s\b)', L('La durata', 'The duration')), re('\w{3,}.{25,}', L('La scena', 'The scene'))], '', 'Onde che si infrangono sugli scogli di Miramare al tramonto, la camera avanza lentamente verso il castello, durata 8 secondi.'), [
            dMatch(pMatch(), [[L('Testo → video', 'Text → video'), L('Clip brevi', 'Short clips')], [L('Sintesi vocale', 'Text-to-speech'), L('Legge un testo', 'Reads text')], [L('Clonazione voce', 'Voice cloning'), L('Serve consenso', 'Needs consent')], [L('Musica generativa', 'Generative music'), L('Brani da una descrizione', 'Songs from a description')], [L('Trascrizione', 'Transcription'), L('Audio → testo', 'Audio → text')]], L('Oltre le immagini.', 'Beyond images.')),
            dFlash(pFlash(), [[L('Un’immagine si può animare in un video', 'An image can be animated into a video'), true], [L('La clonazione vocale senza consenso è sempre lecita', 'Voice cloning without consent is always lawful'), false], [L('La sintesi vocale supporta molte lingue', 'Text-to-speech supports many languages'), true], [L('I video generati durano sempre ore', 'Generated videos always last hours'), false]], L('Suoni e movimento.', 'Sound and motion.')),
        ]),
        lesson('ethics', L('Diritti, etichette e deepfake', 'Rights, labels and deepfakes'), [
            P('Prima di usare un contenuto generato in un progetto, controlla le **condizioni d’uso** dello strumento (uso commerciale, proprietà del risultato) e non imitare marchi, opere protette o persone reali. In molti paesi un’immagine generata senza contributo creativo umano non è protetta dal diritto d’autore.', 'Before using generated content in a project, check the tool’s **terms of use** (commercial use, ownership of the output) and do not imitate brands, protected works or real people. In many countries an image generated without human creative contribution is not protected by copyright.'),
            P('Per riconoscere i contenuti generati esistono **etichette**: metadati come le **Content Credentials** (standard C2PA) e filigrane invisibili come **SynthID** di Google. L’AI Act europeo chiede di dichiarare i contenuti artificiali, in particolare i **deepfake**: immagini, audio o video realistici di persone che non hanno mai detto o fatto quelle cose.', 'To recognise generated content there are **labels**: metadata such as **Content Credentials** (the C2PA standard) and invisible watermarks such as Google’s **SynthID**. The EU AI Act requires disclosing artificial content, especially **deepfakes**: realistic images, audio or video of people who never said or did those things.'),
        ], [
            Q('e1', L('Che cosa sono le Content Credentials?', 'What are Content Credentials?'), [L('Metadati che indicano come è nato un contenuto', 'Metadata stating how content was made'), L('Una password', 'A password'), L('Un abbonamento', 'A subscription'), L('Un filtro foto', 'A photo filter')], 0, L('Standard C2PA.', 'C2PA standard.')),
            Q('e2', L('Che cos’è un deepfake?', 'What is a deepfake?'), [L('Un contenuto realistico falso con persone reali', 'A realistic fake with real people'), L('Un tipo di font', 'A kind of font'), L('Un videogioco', 'A video game'), L('Un formato di file', 'A file format')], 0, L('Va dichiarato e spesso è illecito.', 'It must be disclosed and is often unlawful.')),
            Q('e3', L('Che cosa controllare prima di usare un’immagine generata in un prodotto?', 'What to check before using a generated image in a product?'), [L('Le condizioni d’uso dello strumento', 'The tool’s terms of use'), L('Il colore dominante', 'The dominant colour'), L('Niente', 'Nothing'), L('La risoluzione dello schermo', 'Screen resolution')], 0, L('Uso commerciale e proprietà.', 'Commercial use and ownership.')),
        ], task('text', L('Scrivi una breve dichiarazione da mettere sotto un’immagine generata con l’AI per un articolo, che citi lo **strumento** e che l’immagine è **generata**.', 'Write a short caption to put under an AI-generated image in an article, naming the **tool** and stating the image is **generated**.'), '', [re('generat|creat[ao] con|made with|created with', L('Dichiari che è generata', 'You state it is generated')), re('\bAI\b|\bIA\b|intelligenza artificiale|artificial intelligence|Midjourney|Firefly|DALL|Stable Diffusion|Flux|Gemini|ChatGPT', L('Citi lo strumento o l’AI', 'You name the tool or AI'))], '', 'Immagine generata con l’intelligenza artificiale (Adobe Firefly), a scopo illustrativo.'), [
            dMatch(pMatch(), [['C2PA', L('Standard per le Content Credentials', 'Standard for Content Credentials')], ['SynthID', L('Filigrana invisibile', 'Invisible watermark')], ['Deepfake', L('Falso realistico di persone', 'Realistic fake of people')], ['AI Act', L('Obbligo di dichiarare i contenuti artificiali', 'Duty to disclose artificial content')]], L('Trasparenza nei media.', 'Transparency in media.')),
            dFlash(pFlash(), [[L('Conviene leggere le condizioni d’uso prima dell’uso commerciale', 'Reading the terms before commercial use is wise'), true], [L('Si possono creare deepfake di persone reali liberamente', 'Deepfakes of real people can be made freely'), false], [L('Esistono filigrane invisibili per i contenuti AI', 'There are invisible watermarks for AI content'), true], [L('Ogni immagine generata è protetta da copyright', 'Every generated image is copyrighted'), false]], L('Creare con responsabilità.', 'Creating responsibly.')),
        ]),
        lesson('editing', L('Modificare e rifinire', 'Editing and refining'), [
            P('Raramente la prima immagine è quella giusta. L’**inpainting** rigenera solo una zona scelta (un oggetto da togliere, una mano da correggere); l’**outpainting** allarga l’immagine oltre i bordi; l’**upscaling** aumenta la risoluzione per la stampa.', 'The first image is rarely the right one. **Inpainting** regenerates only a chosen area (an object to remove, a hand to fix); **outpainting** extends the image beyond its edges; **upscaling** raises the resolution for print.'),
            P('Per una serie coerente (lo stesso personaggio in più scene) usa un’**immagine di riferimento** e descrizioni ripetute uguali. Cambia **una cosa alla volta** tra un tentativo e l’altro: così capisci quale parola ha fatto la differenza.', 'For a consistent series (the same character in several scenes) use a **reference image** and repeat the same descriptions. Change **one thing at a time** between attempts: that way you see which word made the difference.'),
        ], [
            Q('ed1', L('Che cosa fa l’inpainting?', 'What does inpainting do?'), [L('Rigenera solo una zona scelta', 'Regenerates only a chosen area'), L('Allarga l’immagine', 'Extends the image'), L('Aumenta la risoluzione', 'Raises the resolution'), L('Toglie i metadati', 'Removes metadata')], 0, L('Ritocchi mirati.', 'Targeted touch-ups.')),
            Q('ed2', L('Che cosa fa l’upscaling?', 'What does upscaling do?'), [L('Aumenta la risoluzione', 'Raises the resolution'), L('Cambia lo stile', 'Changes the style'), L('Aggiunge oggetti', 'Adds objects'), L('Riduce i colori', 'Reduces colours')], 0, L('Utile per la stampa.', 'Useful for print.')),
            Q('ed3', L('Come capisci quale parola conta nel prompt?', 'How do you find which word matters in the prompt?'), [L('Cambiando una cosa alla volta', 'By changing one thing at a time'), L('Cambiando tutto ogni volta', 'By changing everything each time'), L('Scrivendo in maiuscolo', 'By writing in capitals'), L('Non si può', 'You cannot')], 0, L('Come un esperimento.', 'Like an experiment.')),
        ], task('text', L('Abbina in tre righe `inpainting:`, `outpainting:` e `upscaling:` a ciò che fanno.', 'Match in three lines `inpainting:`, `outpainting:` and `upscaling:` to what they do.'), '', [re('^inpainting\s*:.*(zona|area|parte|part)', L('Inpainting giusto', 'Inpainting right')), re('^outpainting\s*:.*(bord|allarg|estend|edge|extend)', L('Outpainting giusto', 'Outpainting right')), re('^upscaling\s*:.*(risoluz|resolution|grand|bigger)', L('Upscaling giusto', 'Upscaling right'))], '', "inpainting: rigenera una zona scelta\noutpainting: allarga oltre i bordi\nupscaling: aumenta la risoluzione"), [
            dMatch(pMatch(), [['Inpainting', L('Ritocca una zona', 'Retouches an area')], ['Outpainting', L('Allarga i bordi', 'Extends the edges')], ['Upscaling', L('Più risoluzione', 'More resolution')], [L('Immagine di riferimento', 'Reference image'), L('Personaggio coerente', 'Consistent character')]], L('Gli attrezzi del ritocco.', 'Editing tools.')),
            dFlash(pFlash(), [[L('Cambiare una cosa alla volta aiuta a capire', 'Changing one thing at a time helps understanding'), true], [L('La prima immagine è sempre la migliore', 'The first image is always the best'), false], [L('L’inpainting può togliere un oggetto', 'Inpainting can remove an object'), true], [L('L’upscaling cambia il soggetto', 'Upscaling changes the subject'), false]], L('Rifinire con metodo.', 'Refining with method.')),
        ]),
    ],
];
